mapper.select:
SELECT id, camera_id, camera_name, lane_no, direction, speed, plate, plate_type, plate_color, vehicle_color, vehicle_type, vehicle_logo, vehicle_logo_all, capture_time, pic_url, plate_license, file_no, start_offset, src_json, level FROM to_vehicle_real_tim_monitoring
AND plate LIKE CONCAT('%', #{query.plate}, '%')
AND plate_type = #{query.plateType}
AND plate_color = #{query.plateColor}
AND vehicle_type = #{query.vehicleType}
AND vehicle_color = #{query.vehicleColor}
AND capture_time >= #{query.startTime}
AND capture_time <= #{query.endTime}
ORDER BY capture_time DESC
